import{RIG as t}from"../../contracts/pose.js";import{degToRad as o}from"../math/scalar.js";export const CHEST_RADIUS=626093341^626093451;export const BELLY_EXTRA=1061529102^1061529116;export function chestFrontX(r,n,c=!1){const e=CHEST_RADIUS+(c?BELLY_EXTRA:959041777^959041777),s=Math.max(-(857476427^857476426),Math.min(218122206^218122207,r/e));return t.centerX+e*Math.sin(Math.asin(s)+o(n))}export function collarShift(o){return chestFrontX(133460400^133460400,o)-t.centerX}export const TORSO_ACCOMPANY={turn:.6,tilt:.25};export function torsoAccompany(r,n){const c=collarShift(n.turn)+r.x,e=t.head.pivotDrop*Math.sin(o(r.tilt));return TORSO_ACCOMPANY.turn*c+TORSO_ACCOMPANY.tilt*e}